package org.example.socialmediabackend.controller;
import org.example.socialmediabackend.model.*;import org.example.socialmediabackend.repository.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/follow") public class FollowController {
 private final FollowRepository follows;private final UserRepository users;public FollowController(FollowRepository f,UserRepository u){follows=f;users=u;}
 @PostMapping public ResponseEntity<?> follow(@RequestBody Map<String,Object> b,Authentication auth){User actor=users.findByEmailIgnoreCase(auth.getName()).orElseThrow();Long followerId=toLong(b.get("followerId")),followingId=toLong(b.get("followingId"));if(followingId==null)return ResponseEntity.badRequest().body(Map.of("message","followingId is required"));if(followerId!=null&&!followerId.equals(actor.getId()))return ResponseEntity.status(403).body(Map.of("message","You can only follow from your own account"));User target=users.findById(followingId).orElseThrow(()->new org.example.socialmediabackend.exception.ResourceNotFoundException("User not found"));if(target.getId().equals(actor.getId()))return ResponseEntity.badRequest().body(Map.of("message","You cannot follow yourself"));if(follows.findByFollowerIdAndFollowingId(actor.getId(),target.getId()).isEmpty()){Follow f=new Follow();f.setFollower(actor);f.setFollowing(target);follows.save(f);}return ResponseEntity.ok(Map.of("message","Followed successfully"));}
 private Long toLong(Object o){try{return Long.valueOf(o.toString());}catch(Exception e){return null;}}
}
